// TypeScript Version: 4.1

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the computation was successful.
* -   if less than zero, then the `-i`th argument had an illegal value.
*/
type StatusCode = number;

/**
* Interface describing `dgelq2`.
*/
interface Routine {
	/**
	* Computes the LQ factorization of a real M-by-N matrix `A = L * Q`, using Householder reflections (unblocked algorithm).
	*
	* ## Notes
	*
	* -   On exit, the elements on and below the diagonal of `A` contain the `M-by-min(M,N)` lower trapezoidal matrix `L`.
	* -   The elements above the diagonal, with the array `TAU`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
	*
	* @param order - storage layout
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input/output matrix
	* @param LDA - stride of the first dimension of `A` (i.e., leading dimension of `A`)
	* @param TAU - output array of scalar factors (length min(M,N))
	* @param WORK - workspace array (length >= M)
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
	* var TAU = new Float64Array( 3 );
	* var work = new Float64Array( 3 );
	*
	* dgelq2( 'column-major', 3, 4, A, 3, TAU, work );
	* // A => <Float64Array>[ ~-5.477, ~-12.78, ~-20.083, ~0.309, ~-3.266, ~-6.532, ~0.463, ~-0.327, ~0, ~0.618, ~-0.789, ~0.618 ]
	* // TAU => <Float64Array>[ ~1.183, ~1.156, ~1.447 ]
	* // work => <Float64Array>[ ~6.532, ~24.593, 0 ]
	*/
	( order: string, M: number, N: number, A: Float64Array, LDA: number, TAU: Float64Array, WORK: Float64Array ): StatusCode;

	/**
	* Computes an LQ factorization of a real M-by-N matrix `A = L * Q`, using Householder reflections (unblocked algorithm) using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   On exit, the elements on and below the diagonal of `A` contain the `M-by-min(M,N)` lower trapezoidal matrix `L`.
	* -   The elements above the diagonal, with the array `TAU`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
	*
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input/output matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param TAU - output array of scalar factors (length min(M,N))
	* @param strideTAU - stride for `TAU`
	* @param offsetTAU - starting index for `TAU`
	* @param WORK - workspace array (length >= M)
	* @param strideWORK - stride for `WORK`
	* @param offsetWORK - starting index for `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
	* var TAU = new Float64Array( 3 );
	* var work = new Float64Array( 3 );
	*
	* dgelq2.ndarray( 3, 4, A, 1, 3, 0, TAU, 1, 0, work, 1, 0 );
	* // A => <Float64Array>[ ~-5.477, ~-12.78, ~-20.083, ~0.309, ~-3.266, ~-6.532, ~0.463, ~-0.327, ~0, ~0.618, ~-0.789, ~0.618 ]
	* // TAU => <Float64Array>[ ~1.183, ~1.156, ~1.447 ]
	* // work => <Float64Array>[ ~6.532, ~24.593, 0 ]
	*/
	ndarray( M: number, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, TAU: Float64Array, strideTAU: number, offsetTAU: number, WORK: Float64Array, strideWORK: number, offsetWORK: number ): StatusCode;
}

/**
* LAPACK routine to compute an LQ factorization of a real M-by-N matrix `A = L * Q`, using Householder reflections (unblocked algorithm).
*
* ## Notes
*
* -   On exit, the elements on and below the diagonal of `A` contain the `M-by-min(M,N)` lower trapezoidal matrix `L`.
* -   The elements above the diagonal, with the array `TAU`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
*
* @param order - storage layout
* @param M - number of rows in `A`
* @param N - number of columns in `A`
* @param A - input/output matrix
* @param LDA - stride of the first dimension of `A` (i.e., leading dimension of `A`)
* @param TAU - output array of scalar factors (length min(M,N))
* @param WORK - workspace array (length >= M)
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
* var TAU = new Float64Array( 3 );
* var work = new Float64Array( 3 );
*
* dgelq2( 'column-major', 3, 4, A, 3, TAU, work );
* // A => <Float64Array>[ ~-5.477, ~-12.78, ~-20.083, ~0.309, ~-3.266, ~-6.532, ~0.463, ~-0.327, ~0, ~0.618, ~-0.789, ~0.618 ]
* // TAU => <Float64Array>[ ~1.183, ~1.156, ~1.447 ]
* // work => <Float64Array>[ ~6.532, ~24.593, 0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
* var TAU = new Float64Array( 3 );
* var work = new Float64Array( 3 );
*
* dgelq2.ndarray( 3, 4, A, 1, 3, 0, TAU, 1, 0, work, 1, 0 );
* // A => <Float64Array>[ ~-5.477, ~-12.78, ~-20.083, ~0.309, ~-3.266, ~-6.532, ~0.463, ~-0.327, ~0, ~0.618, ~-0.789, ~0.618 ]
* // TAU => <Float64Array>[ ~1.183, ~1.156, ~1.447 ]
* // work => <Float64Array>[ ~6.532, ~24.593, 0 ]
*/
declare var dgelq2: Routine;


// EXPORTS //

export = dgelq2;
